/** Dịch tại lúc RENDER (server + client dùng chung): khớp chính xác theo từ điển.
 *  lang="vi" hoặc chưa có bản dịch -> trả nguyên văn. Menu/khung giao diện dùng hàm này
 *  để chữ đúng ngôn ngữ ngay từ bản vẽ đầu tiên, không qua lớp vá DOM.
 *  ov = bản dịch tuỳ chỉnh của ngôn ngữ đó (Admin → Ngôn ngữ, lưu DB): {chuỗi Việt: bản dịch},
 *  được ưu tiên hơn từ điển gốc. */
export function tr(lang: string, text: string, ov?: Record<string, string>): string {
  if (!lang || lang === "vi") return text;
  const o = ov?.[text];
  if (o) return o;
  const v = (DICT[text] as unknown as Record<string, string> | undefined)?.[lang];
  return v || text;
}
/** Như tr() nhưng thêm dịch theo mảnh cho dòng ghép CÓ SỐ (đúng luật của lớp hiển thị). */
export function trd(lang: string, text: string, ov?: Record<string, string>): string {
  const exact = tr(lang, text, ov);
  if (exact !== text || !lang || lang === "vi" || !/\d/.test(text)) return exact;
  let out = text;
  for (const [frag, map] of FRAGMENTS) { const r = map[lang]; if (r && out.includes(frag)) out = out.split(frag).join(r); }
  return out;
}

/* Tiền tệ HIỂN THỊ chỉ còn VND + USD (lệnh Tín 2026-11-08 21:46): các mã
 * khác đã bỏ khỏi danh sách — cookie smmv2-cur lưu mã cũ sẽ rơi về VND ở
 * getCur() (đối chiếu theo đúng danh sách này) và formatMoney cũng tự rơi
 * về định dạng VNĐ khi không tra thấy mã. Tiền nạp crypto (USDT/USDC) là
 * tài sản nạp, KHÔNG phải tiền tệ hiển thị — không nằm trong danh sách này. */
export const CURRENCIES: { key: string; name: string; rate: number }[] = [
  { key: "VND", name: "VND ₫", rate: 1 },
  { key: "USD", name: "USD $", rate: 25000 },
];
export type CurrencyKey = string;

export const LOCALES: Record<string, string> = { vi: "vi-VN", en: "en-US", zh: "zh-CN", th: "th-TH", ja: "ja-JP", ko: "ko-KR" };

/** Định dạng tiền TẠI LÚC RENDER — đã tách hẳn khỏi cơ chế dịch (trước đây lớp vá DOM
 *  dùng regex thay "…đ" sau khi trang hiện). vndInt = số tiền VND (đơn vị tiền thật);
 *  cur = tiền tệ hiển thị khách đã chọn (cookie smmv2-cur); rates = tỉ giá VND/1 đơn vị
 *  ngoại tệ theo cấu hình (settings/panel) — thiếu thì dùng tỉ giá mặc định ở CURRENCIES.
 *  cur = VND -> đúng định dạng của vnd() hiện tại ("55.000đ"). */
export function formatMoney(vndInt: number, cur: string, lang: string, rates?: Record<string, number>): string {
  if (!cur || cur === "VND") return new Intl.NumberFormat("vi-VN").format(Math.round(vndInt)) + "đ";
  const def = CURRENCIES.find((c) => c.key === cur);
  const rate = rates && rates[cur] > 0 ? rates[cur] : def?.rate;
  if (!def || !rate) return new Intl.NumberFormat("vi-VN").format(Math.round(vndInt)) + "đ";
  const val = vndInt / rate;
  const zero = cur === "JPY" || cur === "KRW";
  return new Intl.NumberFormat(LOCALES[lang] || "en-US", {
    style: "currency",
    currency: cur,
    minimumFractionDigits: zero ? 0 : undefined,
    maximumFractionDigits: zero ? 0 : 2,
  }).format(val);
}

